#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(pair_sum_indices(&[4, 9, 1, 6], 7), (2, 3));
    }

    #[test]
    fn first_and_last() {
        assert_eq!(pair_sum_indices(&[5, 1, 2, 8], 13), (0, 3));
    }

    #[test]
    fn duplicates() {
        assert_eq!(pair_sum_indices(&[3, 3], 6), (0, 1));
    }

    #[test]
    fn negatives() {
        assert_eq!(pair_sum_indices(&[-4, 10, 2, -7], -11), (0, 3));
    }

    #[test]
    fn zero_target() {
        assert_eq!(pair_sum_indices(&[0, 5, -5, 9], 0), (1, 2));
    }
}
